create or replace TABLE KFL_PRODUCTION.DBP_DATA.ART_GP_WUP_ZU_PER_1 cluster by (mandant_id)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH.',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner-ID (Lieferanten-ID).',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Der WUP_1 beinhaltet Märkte und Läger. WUP_1 = WarenUmschlagsPlatz, Mutter Wup_1-ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	DAT_VON DATE NOT NULL COMMENT 'Beginn der Gültigkeitsperiode.',
	BEZUGSWEG_ID NUMBER(38,0) NOT NULL COMMENT 'Kennzeichnet, ob der Artikel_1 vom Zentrallager bezogen wird (Bezugsweg = 4) oder direkt vom Lieferanten (Bezugsweg = 1).',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_1 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_1 -> Counter +1.',
	EINKAUFSORGANISATION_ID NUMBER(38,0) COMMENT 'Aus EKORG. Die einkaufsorganisation_id ist erforderlich um einen Lieferanten der Tabelle GP_1 zusammen mit dem Attribut gp_id eindeutig zu identifizieren. 1000 = Warenlieferant, 5000 = Frischelieferant, 9000 = (?) könnte es auch geben.',
	DAT_BIS DATE COMMENT 'Datum, bis zu dem die Zuordnung gilt. Bei bestehenden Zuordnungen: 9999-12-31.',
	EK_BRUTTO NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis brutto (Bedeutung vgl. Kalkulationsschema) aus ABRUT. Tatsächlicher Einkaufspreis. Verwendet den Aktionspreis, wenn vorhanden, ansonsten den Normalpreis.',
	EK_NETTO NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto (Bedeutung vgl. Kalkulationsschema), aus AKNET.',
	EK_NETTONETTO NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis nettonetto (Bedeutung vgl. Kalkulationsschema), aus AKNNE.',
	EK_KAL_BASIS NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Kalkulationsbasis (Bedeutung vgl. Kalkulationsschema), aus EKKBA.',
	EK_MEP NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis ((Bedeutung vgl. Kalkulationsschema), aus MEPRE.',
	EINSTANDSPREIS NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Kaufland Einstandspreis (Bedeutung vgl. Kalkulationsschema), aus LSEIN.\n            Ergibt sich aus dem Einkaufspreis netto einer Ware zuzüglich der Beschaffungskosten oder Bezugskosten und abzüglich der Minderungen, etwa durch Rabatt, Skonto, Bonus.',
	LOGISTIKKOSTENZUSCHLAG NUMBER(18,4) COMMENT 'Logistikkostenzuschlag (ein kalkulierter Wert für die Zentrallagerkosten, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist), aus LOKAU.',
	WRG_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
	KOMPONENTENMENGE NUMBER(18,4) COMMENT 'Menge des Inhalts bei strukturierten Artikeln (Display) - aber nicht Pfandartikeln. Bei nicht strukturierten Artikeln ist der Wert = 1. Die EK-Preise werden mit diesem Wert multipliziert, um zu einem Gesamt-EK pro Artikel_1 zu kommen. Aus KOMPMENG.',
	EK_BRUTTO_NRFB_RAB NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis brutto abzgl. nicht-rabattfähiger Betrag abzgl. Artikelrabatte, aus ABRNA. Verwendet den Aktionspreis, wenn vorhanden, ansonsten den Normalpreis.',
	BONUSBASIS NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'In SAP auch AK-Netto-NRFB genannt. Aus ABONBA. Verwendet den Aktionspreis, wenn vorhanden, ansonsten den Normalpreis.',
	BEZUGSNEBENKOSTEN NUMBER(18,4) COMMENT 'Summe der Bezugsnebenkosten, aus BNK.',
	ZOLLWERT NUMBER(9,4) WITH MASKING POLICY #unknown_policy COMMENT 'Zollwert, betrifft vor allem Importartikel. Aus ZOLLBA.',
	EK_NETTO_BNK NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten, aus AKBN. Verwendet den Aktionspreis, wenn vorhanden, ansonsten den Normalpreis.',
	EK_NETTO_BNK_SACHK NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten plus Sachkosten, aus AKBNS. Verwendet den Aktionspreis, wenn vorhanden, ansonsten den Normalpreis.',
	CYCLE_ID NUMBER(38,0) COMMENT 'Technisches Hilfsfeld. Zur Feststellung der Herkunft des Satzes (Loadfile, Datum).',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	EK_MEP_VOR_FWU NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis vor Festwertumlage: Mit Einführung der Festwertumlage in KMO braucht es einen \"alten\" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.',
	EK_BRUTTO_NORMAL NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis brutto ohne Aktionskonditionen (Bedeutung vgl. Kalkulationsschema). Aus EBRUT. Der Normalpreis / Listenpreis.',
	constraint PK_ART_GP_WUP_ZU_PER primary key (MANDANT_ID, GP_ID, WUP_ID, DAT_VON, BEZUGSWEG_ID, ART_ID)
)COMMENT='TP2 AIS - Artikel_1 Geschäftspartner Markt Zuordnung.'
;